package com.xiaoxiao.pet;
import java.security.*;import java.security.cert.Certificate;import java.security.spec.AlgorithmParameterSpec;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;import java.util.*;import java.io.*;import android.security.keystore.KeyGenParameterSpec;
/** TEST ONLY. Models Keystore storage; does not verify hardware/OS Android Keystore behavior. */
public final class TestKeyStore extends KeyStoreSpi {
 static final Map<String,Key> keys=new HashMap<>();
 static void install(){Security.removeProvider("AndroidKeyStore");Provider p=new Provider("AndroidKeyStore",1.0,"Test-only in-memory Android key store"){};p.put("KeyStore.AndroidKeyStore",TestKeyStore.class.getName());Security.addProvider(p);keys.clear();byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);keys.put("xiaoxiao-api",new SecretKeySpec(bytes,"AES"));}
 public Key engineGetKey(String a,char[] p){return keys.get(a);}public Certificate[] engineGetCertificateChain(String a){return null;}public Certificate engineGetCertificate(String a){return null;}public Date engineGetCreationDate(String a){return new Date();}public void engineSetKeyEntry(String a,Key k,char[] p,Certificate[] c){keys.put(a,k);}public void engineSetKeyEntry(String a,byte[] k,Certificate[] c){throw new UnsupportedOperationException();}public void engineSetCertificateEntry(String a,Certificate c){throw new UnsupportedOperationException();}public void engineDeleteEntry(String a){keys.remove(a);}public Enumeration<String> engineAliases(){return Collections.enumeration(keys.keySet());}public boolean engineContainsAlias(String a){return keys.containsKey(a);}public int engineSize(){return keys.size();}public boolean engineIsKeyEntry(String a){return keys.containsKey(a);}public boolean engineIsCertificateEntry(String a){return false;}public String engineGetCertificateAlias(Certificate c){return null;}public void engineStore(OutputStream o,char[] p){}public void engineLoad(InputStream i,char[] p){}
 public static final class Generator extends KeyGeneratorSpi {String alias;protected void engineInit(SecureRandom r){}protected void engineInit(int n,SecureRandom r){}protected void engineInit(AlgorithmParameterSpec p,SecureRandom r){alias=((KeyGenParameterSpec)p).getKeystoreAlias();}protected SecretKey engineGenerateKey(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);SecretKey k=new SecretKeySpec(bytes,"AES");keys.put(alias,k);return k;}}
}
